# GMAT Focus Quantitative Reasoning: problem solving only, no calculator,
# five options in ascending order. Domains: gmatArith (arithmetic) and
# gmatAlgebra (algebra and word problems). PS(domain, difficulty, skill, stem,
# options, key index, explanation). Items are in presentation order.
A, G = "gmatArith", "gmatAlgebra"

T1 = [
    PS(A, 1, "Percents", r"A store raises the price of a jacket by 20 percent and later lowers the new price by 25 percent. The final price is what percent of the original price?",
       ["90%", "95%", "100%", "105%", "120%"], 0,
       r"Multiply the factors: $1.2 \times 0.75 = 0.9$, so the final price is 90 percent of the original. The changes do not cancel because the 25 percent cut is taken from a larger number."),
    PS(G, 1, "Linear equations", r"If $\frac{x+3}{2} = \frac{2x-1}{3}$, what is the value of $x$?",
       ["1", "5", "7", "9", "11"], 4,
       r"Cross-multiply: $3(x+3) = 2(2x-1)$, so $3x + 9 = 4x - 2$ and $x = 11$."),
    PS(A, 2, "Number properties", r"If $n$ is a positive integer and $n^2$ is divisible by 72, what is the least possible value of $n$?",
       ["4", "6", "8", "12", "24"], 3,
       r"$72 = 2^3 \cdot 3^2$. For $n^2$ to contain $2^3$, $n$ needs at least $2^2$ (since $n^2$ then has $2^4$); for $3^2$, $n$ needs one 3. The least $n$ is $2^2 \cdot 3 = 12$. Check: $144 / 72 = 2$."),
    PS(G, 2, "Exponents", r"If $2^x \cdot 4^{x+1} = 2^{11}$, what is the value of $x$?",
       ["1", "2", "3", "4", "5"], 2,
       r"Write 4 as $2^2$: $2^x \cdot 2^{2x+2} = 2^{3x+2}$. Then $3x + 2 = 11$, so $x = 3$."),
    PS(A, 2, "Ratios", r"In a class, the ratio of first-year to second-year students is 3 to 5. After 6 more first-year students join and no one leaves, the ratio becomes 3 to 4. How many second-year students are in the class?",
       ["18", "24", "30", "35", "40"], 4,
       r"Let the counts be $3k$ and $5k$. Then $\frac{3k+6}{5k} = \frac{3}{4}$, so $12k + 24 = 15k$ and $k = 8$. Second-year students: $5 \cdot 8 = 40$."),
    PS(G, 2, "Word problems", r"A theater sold 40 tickets for a total of \$380. Adult tickets cost \$12 and child tickets cost \$7. How many adult tickets were sold?",
       ["20", "22", "24", "26", "28"], 0,
       r"With $a$ adult tickets, $12a + 7(40 - a) = 380$, so $5a + 280 = 380$ and $a = 20$."),
    PS(A, 1, "Averages", r"The average (arithmetic mean) of five numbers is 18. When one of the numbers is removed, the average of the remaining four numbers is 16. What number was removed?",
       ["26", "28", "30", "32", "34"], 0,
       r"The five numbers sum to $5 \cdot 18 = 90$ and the four to $4 \cdot 16 = 64$. The removed number is $90 - 64 = 26$."),
    PS(G, 3, "Quadratics", r"If $r$ and $s$ are the two solutions of $x^2 - 5x - 14 = 0$, what is the value of $r^2 + s^2$?",
       ["45", "49", "53", "57", "65"], 2,
       r"Factor: $(x - 7)(x + 2) = 0$, so the solutions are 7 and $-2$. Then $49 + 4 = 53$. (Or use $r^2 + s^2 = (r+s)^2 - 2rs = 25 + 28 = 53$.)"),
    PS(A, 2, "Rates and work", r"Working alone at a constant rate, machine A makes 120 parts in 4 hours. Machine B, also at a constant rate, makes 120 parts in 6 hours. Working together, how many hours will the two machines take to make 300 parts?",
       ["2.5", "3", "4", "5", "6"], 4,
       r"A makes 30 parts an hour and B makes 20, so together they make 50 an hour. $300 / 50 = 6$ hours."),
    PS(G, 2, "Inequalities", r"How many integers $x$ satisfy $-3 < 2x + 5 \le 9$?",
       ["3", "4", "5", "6", "7"], 3,
       r"Subtract 5: $-8 < 2x \le 4$. Divide by 2: $-4 < x \le 2$. The integers are $-3, -2, -1, 0, 1, 2$: six of them."),
    PS(A, 2, "Counting", r"How many three-digit positive integers have only odd digits?",
       ["100", "125", "150", "225", "250"], 1,
       r"Each of the three places can be 1, 3, 5, 7 or 9, so there are $5 \cdot 5 \cdot 5 = 125$ such integers."),
    PS(G, 3, "Absolute value", r"What is the sum of all values of $x$ for which $|x - 4| = 2x + 1$?",
       ["$-5$", "$-4$", "1", "3", "5"], 2,
       r"If $x - 4 = 2x + 1$, then $x = -5$, but then $2x + 1 = -9$, which cannot equal an absolute value, so reject it. If $4 - x = 2x + 1$, then $x = 1$, and $|1 - 4| = 3 = 2(1) + 1$. The only solution is 1, so the sum is 1."),
    PS(A, 2, "Probability", r"A bag holds 4 red marbles and 6 blue marbles. Two marbles are drawn at random without replacement. What is the probability that both are blue?",
       [r"$\frac{1}{5}$", r"$\frac{4}{15}$", r"$\frac{1}{3}$", r"$\frac{9}{25}$", r"$\frac{2}{5}$"], 2,
       r"$\frac{6}{10} \cdot \frac{5}{9} = \frac{30}{90} = \frac{1}{3}$. The answer $\frac{9}{25}$ would be right only with replacement."),
    PS(G, 1, "Functions", r"If $f(x) = 2x^2 - 3$, what is the value of $f(f(1))$?",
       ["$-5$", "$-1$", "1", "3", "5"], 1,
       r"$f(1) = 2 - 3 = -1$, and $f(-1) = 2(1) - 3 = -1$. So $f(f(1)) = -1$."),
    PS(A, 2, "Remainders", r"When the positive integer $k$ is divided by 6, the remainder is 4. What is the remainder when $5k$ is divided by 6?",
       ["1", "2", "3", "4", "5"], 1,
       r"Write $k = 6q + 4$. Then $5k = 30q + 20 = 6(5q + 3) + 2$, so the remainder is 2. A quick check: $k = 4$ gives $5k = 20$, remainder 2."),
    PS(G, 2, "Rate equations", r"A delivery van travels 90 miles to a depot at 45 miles per hour and returns along the same road at 30 miles per hour. What is the average speed, in miles per hour, for the whole trip?",
       ["35", "36", "37.5", "38", "40"], 1,
       r"Average speed is total distance over total time: $\frac{180}{2 + 3} = 36$. Averaging 45 and 30 to get 37.5 ignores that more time is spent at the slower speed."),
    PS(A, 2, "Compound interest", r"An investment of \$5,000 earns 4 percent annual interest, compounded annually. To the nearest dollar, what is it worth after 2 years?",
       [r"\$5,200", r"\$5,300", r"\$5,400", r"\$5,408", r"\$5,500"], 3,
       r"$5{,}000 \times 1.04^2 = 5{,}000 \times 1.0816 = 5{,}408$. Simple interest would give \$5,400; compounding adds interest on the first year's \$200."),
    PS(G, 2, "Sequences", r"In a sequence, $a_1 = 3$ and each term after the first is 2 more than twice the term before it. What is $a_4$?",
       ["38", "42", "46", "74", "78"], 0,
       r"$a_2 = 2(3) + 2 = 8$, $a_3 = 2(8) + 2 = 18$, $a_4 = 2(18) + 2 = 38$."),
    PS(A, 1, "Roots", r"What is the value of $\sqrt{50} + \sqrt{18}$?",
       [r"$4\sqrt{2}$", r"$5\sqrt{2}$", r"$6\sqrt{2}$", r"$7\sqrt{2}$", r"$8\sqrt{2}$"], 4,
       r"$\sqrt{50} = 5\sqrt{2}$ and $\sqrt{18} = 3\sqrt{2}$, so the sum is $8\sqrt{2}$. Roots of a sum do not combine as $\sqrt{68}$."),
    PS(G, 3, "Ratios in expressions", r"If $\frac{a}{b} = \frac{3}{4}$ and $b \ne 0$, what is the value of $\frac{2a + b}{a - 2b}$?",
       ["$-2$", "$-1$", "0", "1", "2"], 0,
       r"Any pair in the ratio works, so let $a = 3$ and $b = 4$: $\frac{6 + 4}{3 - 8} = \frac{10}{-5} = -2$."),
    PS(A, 3, "Statistics", r"The set $\{3, 7, 7, 10, x\}$ has a median equal to its mean. Which of the following could be the value of $x$?",
       ["3", "5", "6", "8", "12"], 3,
       r"Whatever $x$ is, the middle value of the sorted set is 7 (two 7s sit in the middle unless $x$ moves one of them, and either way the third value is 7). So the mean must be 7: $\frac{27 + x}{5} = 7$ gives $x = 8$."),
]

T2 = [
    PS(A, 1, "Percents", r"A company's revenue rose 25 percent in one year and fell 20 percent the next year. Over the two years, revenue",
       ["decreased by 5%", "decreased by 1%", "did not change", "increased by 1%", "increased by 5%"], 2,
       r"$1.25 \times 0.8 = 1$, so revenue ended exactly where it started."),
    PS(G, 2, "Linear equations", r"If $5(x - 2) - 3(2x + 1) = -20$, what is the value of $x$?",
       ["$-7$", "$-3$", "3", "7", "33"], 3,
       r"Expand: $5x - 10 - 6x - 3 = -x - 13$. Then $-x - 13 = -20$, so $x = 7$."),
    PS(A, 2, "Number properties", r"How many positive divisors does 180 have?",
       ["6", "9", "12", "16", "18"], 4,
       r"$180 = 2^2 \cdot 3^2 \cdot 5$. The number of divisors is $(2+1)(2+1)(1+1) = 18$."),
    PS(G, 2, "Quadratics", r"If $(x - 3)^2 = 49$, what is the product of the possible values of $x$?",
       ["$-40$", "$-21$", "$-4$", "10", "40"], 0,
       r"$x - 3 = 7$ or $x - 3 = -7$, so $x = 10$ or $x = -4$. Their product is $-40$."),
    PS(A, 2, "Mixtures", r"A 40-liter solution is 25 percent acid. How many liters of pure acid must be added to make a solution that is 40 percent acid?",
       ["10", "12", "15", "16", "20"], 0,
       r"The solution has 10 liters of acid. Adding $x$ liters: $\frac{10 + x}{40 + x} = 0.4$, so $10 + x = 16 + 0.4x$, $0.6x = 6$ and $x = 10$."),
    PS(G, 2, "Systems of equations", r"If $2x + 3y = 13$ and $4x - y = 5$, what is the value of $x + y$?",
       ["3", "4", "5", "6", "7"], 2,
       r"From the second equation, $y = 4x - 5$. Substitute: $2x + 12x - 15 = 13$, so $x = 2$ and $y = 3$. Then $x + y = 5$."),
    PS(A, 1, "Weighted averages", r"Group A has 20 students with an average score of 70. Group B has 30 students with an average score of 80. What is the average score of all 50 students?",
       ["74", "75", "76", "77", "78"], 2,
       r"$\frac{20 \cdot 70 + 30 \cdot 80}{50} = \frac{1{,}400 + 2{,}400}{50} = 76$. It is closer to 80 because group B is larger."),
    PS(G, 2, "Inequalities", r"A phone plan costs \$30 a month plus \$0.10 for each minute over 300 minutes. If a month's bill is at most \$45, what is the greatest number of minutes that could have been used?",
       ["150", "300", "350", "400", "450"], 4,
       r"The overage is at most \$15, which buys $15 / 0.10 = 150$ extra minutes. So at most $300 + 150 = 450$ minutes."),
    PS(A, 2, "Rates", r"Two trains start 300 miles apart and travel toward each other on parallel tracks, one at 70 miles per hour and the other at 80 miles per hour. When they pass each other, how many miles has the slower train traveled?",
       ["140", "150", "160", "170", "180"], 0,
       r"They close the gap at $70 + 80 = 150$ miles per hour, so they meet after 2 hours. The slower train has gone $70 \cdot 2 = 140$ miles."),
    PS(G, 1, "Exponents", r"What is the value of $\frac{9^4 \cdot 27^2}{3^{12}}$?",
       ["3", "9", "27", "81", "243"], 1,
       r"$9^4 = 3^8$ and $27^2 = 3^6$, so the fraction is $\frac{3^{14}}{3^{12}} = 3^2 = 9$."),
    PS(A, 3, "Counting", r"A committee of 3 people is chosen from 5 men and 4 women. How many different committees include at least one woman?",
       ["10", "40", "64", "70", "74"], 4,
       r"All committees: $\binom{9}{3} = 84$. Committees with no woman: $\binom{5}{3} = 10$. So $84 - 10 = 74$ include at least one woman."),
    PS(G, 2, "Functions", r"If $g(x) = 3x + k$ and $g(g(2)) = 30$, what is the value of $k$?",
       ["2", "3", "4", "6", "8"], 1,
       r"$g(2) = 6 + k$. Then $g(6 + k) = 3(6 + k) + k = 18 + 4k = 30$, so $k = 3$."),
    PS(A, 2, "Probability", r"Two fair six-sided dice are rolled. What is the probability that the sum of the numbers rolled is 8?",
       [r"$\frac{1}{9}$", r"$\frac{5}{36}$", r"$\frac{1}{6}$", r"$\frac{7}{36}$", r"$\frac{2}{9}$"], 1,
       r"The pairs (2,6), (3,5), (4,4), (5,3) and (6,2) give 8: five of the 36 equally likely outcomes."),
    PS(G, 3, "Work problems", r"Working alone, Ana takes 4 hours longer than Ben to paint a room. Working together at their usual rates, they paint the room in 3 hours and 45 minutes. How many hours does Ben take working alone?",
       ["3", "4", "5", "6", "10"], 3,
       r"Together they take $\frac{15}{4}$ hours. If Ben takes $b$ hours, $\frac{1}{b} + \frac{1}{b+4} = \frac{4}{15}$. Testing the choices: $b = 6$ gives $\frac{1}{6} + \frac{1}{10} = \frac{5 + 3}{30} = \frac{4}{15}$."),
    PS(A, 3, "Units digits", r"What is the units digit of $3^{25} \cdot 7^{10}$?",
       ["1", "3", "5", "7", "9"], 3,
       r"Units digits of powers of 3 cycle 3, 9, 7, 1, and $25 = 4 \cdot 6 + 1$, so $3^{25}$ ends in 3. Powers of 7 cycle 7, 9, 3, 1, and $10 = 4 \cdot 2 + 2$, so $7^{10}$ ends in 9. $3 \cdot 9 = 27$ ends in 7."),
    PS(G, 2, "Percent expressions", r"If $x$ is 50 percent greater than $y$ and $y$ is 20 percent less than $z$, then $x$ is what percent of $z$?",
       ["120%", "125%", "130%", "140%", "150%"], 0,
       r"$x = 1.5y$ and $y = 0.8z$, so $x = 1.5 \cdot 0.8z = 1.2z$, which is 120 percent of $z$."),
    PS(A, 2, "Fractions", r"At a firm, $\frac{2}{5}$ of the employees work remotely. Of the rest, $\frac{3}{4}$ work in the office full time, and the remaining 24 employees work a hybrid schedule. How many employees does the firm have?",
       ["160", "180", "200", "240", "320"], 0,
       r"The non-remote share is $\frac{3}{5}$, and a quarter of it is hybrid: $\frac{1}{4} \cdot \frac{3}{5} = \frac{3}{20}$ of all employees. $\frac{3}{20}E = 24$ gives $E = 160$."),
    PS(G, 2, "Absolute value", r"How many integers $x$ satisfy $|2x - 3| < 7$?",
       ["4", "5", "6", "7", "8"], 2,
       r"$-7 < 2x - 3 < 7$ gives $-4 < 2x < 10$, so $-2 < x < 5$. The integers are $-1, 0, 1, 2, 3, 4$: six."),
    PS(A, 3, "Standard deviation", r"Which of the following sets of numbers has the greatest standard deviation?",
       [r"$\{10, 10, 10, 10, 10\}$", r"$\{6, 8, 10, 12, 14\}$", r"$\{2, 10, 10, 10, 18\}$", r"$\{2, 6, 10, 14, 18\}$", r"$\{9, 10, 10, 10, 11\}$"], 3,
       r"Every set has mean 10, so compare the squared distances from 10. $\{2, 6, 10, 14, 18\}$ gives $64 + 16 + 0 + 16 + 64 = 160$, more than $\{2, 10, 10, 10, 18\}$ with $128$ and $\{6, 8, 10, 12, 14\}$ with $40$."),
    PS(G, 2, "Consecutive integers", r"The sum of five consecutive even integers is 170. What is the greatest of the five?",
       ["30", "32", "34", "36", "38"], 4,
       r"The middle integer is the average, $170 / 5 = 34$, so the five are 30, 32, 34, 36 and 38. The greatest is 38."),
    PS(A, 2, "Comparing fractions", r"Which of the following fractions is greatest?",
       [r"$\frac{5}{8}$", r"$\frac{11}{17}$", r"$\frac{7}{11}$", r"$\frac{9}{14}$", r"$\frac{3}{5}$"], 1,
       r"Compare each with its distance below 1, or convert: $\frac{5}{8} = 0.625$, $\frac{7}{11} \approx 0.636$, $\frac{9}{14} \approx 0.643$, $\frac{3}{5} = 0.6$ and $\frac{11}{17} \approx 0.647$. The greatest is $\frac{11}{17}$."),
]

